package httpapi

import (
	"crypto/x509"
	"io"
	"log/slog"
	"net/http"
	"time"
)

//go:generate optgen generate --source-file $GOFILE

// options are a [Transport]'s tunables, and [NewDiscovery] reads the SSRF
// switch from them too. The With options are generated by go-optgen; a nil
// argument is ignored, and a non-positive duration keeps the default.
type options struct {
	// host carries both clients' requests: the host's round tripper. The
	// SSRF guard is off with it: it cannot see its dials. Discovery does not
	// use it; it has its own client.
	host http.RoundTripper `opt:"RoundTripper" optgen:"notnil"`

	// roots is trusted instead of the system pool, for a server signed by
	// the host's own authority. A host's round tripper brings its own TLS
	// and ignores this.
	roots *x509.CertPool `opt:"RootCAs"`

	// open lets the transport dial private and loopback addresses: a host
	// that runs its own server on its network configures its endpoints, and
	// the composition root turns the guard off for them.
	open bool `opt:"SSRFProtection" optval:"invert"`

	// level is the wire log. The default is off.
	level Level

	// wireWriter receives the wire log. Absent uses the logger at debug.
	wireWriter io.Writer `optgen:"notnil"`

	// log receives the transport's own records and, unless wireWriter
	// replaces it, the wire log. The default is slog.Default as it stands
	// when the transport is built.
	log *slog.Logger `opt:"Logger" optgen:"default=slog.Default()"`

	// responseHeaderTimeout is how long a request that has been written
	// waits for the response headers. A host's round tripper keeps its own.
	responseHeaderTimeout time.Duration `optgen:"default=defaultResponseHeaderTimeout" optval:"positive"`

	// uploadResponseHeaderTimeout is the same wait after a file upload.
	uploadResponseHeaderTimeout time.Duration `optgen:"default=defaultUploadResponseHeaderTimeout" optval:"positive"`

	// idleReadTimeout is how long a body read into memory may go without a
	// byte arriving.
	idleReadTimeout time.Duration `optgen:"default=defaultIdleReadTimeout" optval:"positive"`

	// pingAfter is how long an HTTP/2 connection may stay silent before it
	// is pinged, and pingTimeout how long the ping waits for its answer. A
	// host's round tripper keeps its own.
	pingAfter   time.Duration `optgen:"default=defaultPingAfter" optval:"positive"`
	pingTimeout time.Duration `optgen:"default=defaultPingTimeout" optval:"positive"`
}

// The bounds on a request that has stopped moving. None of them is a
// deadline for the whole request: a transfer that is slow but alive is never
// cut, and the caller's context stays the only overall limit. Each expiry is
// a transport error the retry policy repeats, and three in a row fail the
// operation, so the values sit well clear of the slowest healthy answer
// seen: small reads through a slow VPN took up to 25 seconds.
const (
	// defaultResponseHeaderTimeout bounds a server that accepts a request
	// and never answers. The wait starts once the request is written, so
	// it covers the server's work and one round trip, with nothing arriving
	// in between to show the server is alive; it is the longest of the
	// three for that reason.
	defaultResponseHeaderTimeout = 60 * time.Second

	// defaultUploadResponseHeaderTimeout is that bound after a file upload.
	// The wait starts when the last byte is handed to the connection, not
	// when it arrives: what is still buffered has to cross the uplink, and
	// the server stores and checks the whole file before it answers. A
	// false expiry sends the file again, so the bound is generous.
	defaultUploadResponseHeaderTimeout = 5 * time.Minute

	// defaultIdleReadTimeout bounds a body read into memory that stops
	// arriving after its headers. It restarts with every byte, so it
	// limits silence, not size or duration.
	defaultIdleReadTimeout = 45 * time.Second

	// defaultPingAfter and defaultPingTimeout find a dead HTTP/2 connection
	// in about thirty seconds, whatever the request on it is doing: a file
	// transfer has no other bound. A live server answers the ping, so a
	// slow transfer is not cut.
	defaultPingAfter   = 15 * time.Second
	defaultPingTimeout = 15 * time.Second
)
